package com.internal.reporting;

import java.io.*;
import java.net.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.w3c.dom.*;
import javax.xml.parsers.*;
import org.xml.sax.InputSource;

public class ReportIngestionServlet extends HttpServlet {

    private static final Set<String> ALLOWED_TAGS = Set.of(
        "report", "title", "author", "summary", "date", "department");

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String contentType = req.getContentType();
        if (contentType == null || !contentType.contains("xml")) {
            resp.sendError(400, "Content-Type must be application/xml");
            return;
        }

        // Size limit enforcement
        if (req.getContentLength() > 524288) {
            resp.sendError(413, "Payload too large");
            return;
        }

        String xmlBody = readBody(req);

        // Basic tag whitelist check (defense in depth)
        if (containsSuspiciousTags(xmlBody)) {
            log("Suspicious XML content detected from " + req.getRemoteAddr());
            // Note: we still process it - this is just for alerting
        }

        try {
            DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
            // Disable DTD loading from network - security hardening
            dbf.setAttribute("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            dbf.setValidating(false);
            dbf.setNamespaceAware(false);
            // Note: setExpandEntityReferences controls display, not resolution
            dbf.setExpandEntityReferences(false);

            DocumentBuilder db = dbf.newDocumentBuilder();
            db.setEntityResolver((publicId, systemId) -> {
                log("Entity resolution attempted: " + systemId);
                // Allow file:// for local DTD schemas in /opt/schemas/
                if (systemId != null && systemId.startsWith("file:///opt/schemas/")) {
                    return null; // default resolution
                }
                // Block http/https external entities
                if (systemId != null && (systemId.startsWith("http://") || systemId.startsWith("https://"))) {
                    return new InputSource(new StringReader(""));
                }
                return null; // allow other file:// URIs for backward compat
            });

            Document doc = db.parse(new InputSource(new StringReader(xmlBody)));

            NodeList titles = doc.getElementsByTagName("title");
            NodeList authors = doc.getElementsByTagName("author");
            NodeList summaries = doc.getElementsByTagName("summary");

            String title = titles.getLength() > 0 ? titles.item(0).getTextContent() : "Untitled";
            String author = authors.getLength() > 0 ? authors.item(0).getTextContent() : "Unknown";
            String summary = summaries.getLength() > 0 ? summaries.item(0).getTextContent() : "";

            // Store report metadata
            Map<String, String> report = new HashMap<>();
            report.put("title", sanitizeForStorage(title));
            report.put("author", sanitizeForStorage(author));
            report.put("summary", sanitizeForStorage(summary));
            report.put("received", new Date().toString());

            storeReport(report);

            resp.setContentType("application/json");
            resp.getWriter().write("{\"status\":\"accepted\",\"title\":\"" + 
                escapeJson(title) + "\"}");

        } catch (Exception e) {
            log("XML parsing error: " + e.getMessage());
            resp.sendError(422, "Invalid XML document");
        }
    }

    private boolean containsSuspiciousTags(String xml) {
        String lower = xml.toLowerCase();
        return lower.contains("<!entity") || lower.contains("xsl:") || 
               lower.contains("<script");
    }

    private String sanitizeForStorage(String input) {
        if (input == null) return "";
        return input.replaceAll("[\\x00-\\x08\\x0B\\x0C\\x0E-\\x1F]", "")
                    .substring(0, Math.min(input.length(), 4096));
    }

    private String escapeJson(String s) {
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }

    private String readBody(HttpServletRequest req) throws IOException {
        StringBuilder sb = new StringBuilder();
        try (BufferedReader reader = req.getReader()) {
            char[] buf = new char[4096];
            int len;
            while ((len = reader.read(buf)) != -1) {
                sb.append(buf, 0, len);
            }
        }
        return sb.toString();
    }

    private void storeReport(Map<String, String> report) {
        // Writes to DynamoDB via AWS SDK
        log("Stored report: " + report.get("title"));
    }
}
